import subprocess
def shas(branch, ep):
    out=subprocess.check_output(['git','log','--format=%H',f'origin/{branch}']).decode().split()
    res=[]
    for sha in out:
        msg=subprocess.check_output(['git','show','-s','--format=%B',sha]).decode()
        if 'Friend-Message: 1' in msg and f'Episode: {ep}' in msg:
            res.append(sha)
    return res
ep='S06/E12'
transcript=set()
for line in subprocess.check_output(['git','show',f'origin/main:{ep}.md']).decode().splitlines():
    if line.startswith('Source: friend/'):
        transcript.add(line.split('@')[-1].strip())
missing=0
for b in ['rachel','monica','phoebe','joey','chandler','ross']:
    for sha in shas('friend/'+b, ep):
        if sha not in transcript:
            missing+=1
            print('MISSING', b, sha)
